import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");

  // --- Quote: base premiums per main item type ---
  it.todo("quotes a plain sword -- base premium 100 G");
  it.todo("quotes a plain amulet -- base premium 60 G");
  it.todo("quotes a plain staff -- base premium 80 G");
  it.todo("quotes a plain potion -- base premium 40 G");

  // --- Quote: component base premiums and the building block ---
  it.todo("quotes 1 rune -- base premium 25 G");
  it.todo("quotes 1 moonstone -- base premium 25 G");
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block; block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");
  it.todo("quotes 3 moonstones -- base premium 60 G (block applies per component type)");

  // --- Quote: item-specific modifiers ---
  it.todo("quotes a cursed sword -- adds 50 % of that item's base premium (50 G curse surcharge)");
  it.todo("quotes a sword with enchantment 5 -- adds 30 % high-enchantment surcharge (30 G)");
  it.todo("quotes a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quotes a cursed sword with enchantment 5 -- both surcharges apply (50 G + 30 G)");

  // --- Quote: policy-wide modifiers ---
  it.todo("quotes for a customer with 2 years -- 20 % loyalty discount applies (threshold inclusive)");
  it.todo("quotes for a customer with 1 year -- no loyalty discount");
  it.todo("quotes for a customer with 3 years -- 20 % loyalty discount applies");
  it.todo("quotes any item -- 10 % initial assessment surcharge applies to every quote's items");
  it.todo("quotes a second contract in the same scenario -- 15 % follow-up contract discount applies");
  it.todo("quotes a third contract in the same scenario -- 15 % follow-up contract discount applies");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("quotes a cursed sword + plain amulet -- policy base 160 G, curse surcharge only 50 G (on the cursed item)");

  // --- Quote: rounding in the MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate premium amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer's second quote with a cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote with an unknown item type (e.g. broomstick) -- CLI exits non-zero, error on stderr, no results on stdout");

  // --- Insurance sum and cap ---
  it.todo("policy of one sword -- insurance sum 1000 G, cap 2000 G");
  it.todo("policy of a sword + amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy of two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy of a sword + 3 runes -- insurance sum 1750 G, cap 3500 G (block affects premium only)");
  it.todo("cursed sword (premium 165 G) -- cap 2000 G from the unmodified insurance value");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("claims a steel sword enchantment 3 with damage 500 G -- payout 400 G (full minus 100 G deductible)");
  it.todo("claims a rune (no enchantment, no material) with damage 200 G -- payout 100 G (full minus deductible)");
  it.todo("claims damage below the deductible -- payout 0 G (never negative)");

  // --- Claim: special clauses ---
  it.todo("claims a steel sword enchantment 9 with damage 1000 G -- payout 400 G (50 % clause, then deductible)");
  it.todo("claims a steel sword enchantment 8 with damage 1000 G -- payout 400 G (threshold >= 8 inclusive)");
  it.todo("claims a steel sword enchantment 7 with damage 1000 G -- payout 900 G (no high-enchantment clause)");
  it.todo("claims a dragon-material sword enchantment 5 with damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("claims a dragon-material sword enchantment 8 with damage 1000 G -- payout 400 G (50 % rule wins, then deductible)");
  it.todo("claims a dragon-material sword enchantment 9 with damage 1000 G -- payout 400 G (50 % rule wins, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("claims a dragon attack damaging a sword (500 G) and an amulet (300 G) -- payout 600 G (deductible once per damaged item)");
  it.todo("claims two sword damages on a two-sword policy -- each entry gets its own deductible");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("first claim of 1500 G on a 1000 G sword policy -- payout 1400 G, remainingCap 600 G");
  it.todo("second claim of 1500 G on the same policy -- payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  it.todo("claim after the cap is exhausted -- payout 0 G, remainingCap 0 G");

  // --- Claim: rounding in the MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero, error on stderr");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI produces {premium} for quote steps and {payout, remainingCap} for claim steps");
  it.todo("CLI resolves a claim's policy field to the zero-based index of the earlier quote step");
});
EOF
npx vitest run 2>&1 | tail -15

