const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/** The MHPCO price list for main items: base premium in G per item type. */
const MAIN_ITEM_BASE_PREMIUMS: Readonly<Record<string, number>> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

/** Components such as runes and moonstones share one base premium. */
const COMPONENT_BASE_PREMIUM = 25;

const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function mainItemBasePremiumOf(item: Item): number {
  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? 0;
}

/** A building block of alike components is offered at a special premium. */
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

/** Components count as "alike" -- and so may form a block -- per item type. */
function alikeGroupSizes(components: readonly Item[]): readonly number[] {
  const sizes = new Map<string, number>();
  for (const component of components) {
    sizes.set(component.type, (sizes.get(component.type) ?? 0) + 1);
  }
  return [...sizes.values()];
}

function alikeGroupBasePremium(groupSize: number): number {
  if (groupSize === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_BASE_PREMIUM;
  }
  return groupSize * COMPONENT_BASE_PREMIUM;
}

function componentsBasePremium(components: readonly Item[]): number {
  return alikeGroupSizes(components).reduce(
    (sum, groupSize) => sum + alikeGroupBasePremium(groupSize),
    0,
  );
}

function mainItemsBasePremium(mainItems: readonly Item[]): number {
  return mainItems.reduce((sum, item) => sum + mainItemBasePremiumOf(item), 0);
}

function policyBasePremiumOf(items: readonly Item[]): number {
  return (
    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
    componentsBasePremium(items.filter(isComponent))
  );
}

function applyPolicyWideModifiers(policyBasePremium: number): number {
  const firstInsuranceSurcharge =
    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return policyBasePremium + firstInsuranceSurcharge;
}

export function quote(
  customer: Customer,
  items: readonly Item[],
  previousContracts: number,
): number {
  return applyPolicyWideModifiers(policyBasePremiumOf(items)) + PROCESSING_FEE;
}

