=== quote ===
import { componentsBasePremium, isComponent } from "./component-block.js";
import {
  mainItemsBasePremium,
  mainItemsRiskSurcharges,
} from "./main-item.js";

export interface Customer {
  readonly yearsWithMHPCO: number;
}

export interface Item {
  readonly type: string;
  readonly material?: string;
  readonly enchantment?: number;
  readonly cursed?: boolean;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/**
 * Every item in a quote is treated as a first insurance, regardless of
 * customer history, so this surcharge scales the policy base premium.
 */
function firstInsuranceSurcharge(policyBasePremium: number): number {
  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

export function quote(
  customer: Customer,
  items: readonly Item[],
  previousContracts: number,
): number {
  // Each item is priced by the pricing policy that governs its kind:
  // components may form blocks, main items follow the price list.
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);

  const policyBasePremium =
    mainItemsBasePremium(mainItems) + componentsBasePremium(components);

  return (
    policyBasePremium +
    mainItemsRiskSurcharges(mainItems) +
    firstInsuranceSurcharge(policyBasePremium) +
    PROCESSING_FEE
  );
}

