import type { Customer } from "./policy.js";

/**
 * Policy-wide modifiers scale the policy base premium (the sum of all item
 * base premiums). Item-specific modifiers live with the items they affect.
 *
 * Two independent policies live here, and they answer to different facts:
 * the initial assessment surcharge is a property of the quote itself, while
 * the loyalty discount is a property of the customer's relationship with
 * the MHPCO.
 */

/** Long-standing customers are rewarded with a loyalty discount. */
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS = 2;

const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;

function isLongStanding(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

/** What the customer's standing with the MHPCO earns them off the premium. */
export function customerStandingDiscount(
  customer: Customer,
  policyBasePremium: number,
): number {
  return isLongStanding(customer)
    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
    : 0;
}

/**
 * Every item in a quote is assessed as a first insurance, regardless of
 * customer history, so this surcharge always scales the policy base premium.
 */
export function initialAssessmentSurcharge(policyBasePremium: number): number {
  return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
}
=== quote ===
import { priceItems } from "./item-pricing.js";
import type { Customer, Item } from "./policy.js";
import {
  customerStandingDiscount,
  initialAssessmentSurcharge,
} from "./policy-modifier.js";

const PROCESSING_FEE = 5;

/**
 * Item-specific modifiers apply to the base premium of the affected item;
 * policy-wide modifiers apply to the policy base premium; the processing
 * fee is added at the very end.
 *
 * `previousContracts` is not read yet: the 15 % follow-up contract discount
 * is not an active behavior. Rounding is likewise not active, so a premium
 * may still come out as a fraction.
 */
export function quote(
  customer: Customer,
  items: readonly Item[],
  previousContracts: number,
): number {
  const { basePremium, riskSurcharges } = priceItems(items);

  return (
    basePremium +
    riskSurcharges +
    initialAssessmentSurcharge(basePremium) -
    customerStandingDiscount(customer, basePremium) +
    PROCESSING_FEE
  );
}

