# base premiums achievable: main items sums + component groups
# search small policies for a case where end-rounding != per-step rounding
def end(base, loy, fu):
    fi = base*0.1
    l = base*0.2 if loy else 0
    f = base*0.15 if fu else 0
    return math.ceil(base + fi - l - f + 5)
def perstep(base, loy, fu):
    fi = math.ceil(base*0.1)
    l = math.ceil(base*0.2) if loy else 0
    f = math.ceil(base*0.15) if fu else 0
    return math.ceil(base + fi - l - f + 5)
for base in [25,50,75,100,175,125,150,225,250,60,120,80,40,140,160,180,220]:
