python3 - <<'PY'
p='src/claim.ts'
s=open(p).read()
s=s.replace('''/**
 * What one damage settles at. No special clause has an active example yet,
 * so a damage is reimbursed in full and the deductible is taken off.
 */
function payoutForDamage(damage: Damage): number {
  return Math.max(damage.amount - DEDUCTIBLE, NOTHING_PAID_OUT);
}''','''/** Damage to a highly enchanted item is reimbursed at half its amount. */
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;

const FULL_REIMBURSEMENT_RATE = 1;

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
}

/** What share of a damage the MHPCO reimburses, before the deductible. */
function reimbursementRateOf(item: Item): number {
  return isHighlyEnchanted(item)
    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : FULL_REIMBURSEMENT_RATE;
}

function damagedItem(items: readonly Item[], damage: Damage): Item {
  return items.find((item) => item.type === damage.itemType) ?? {
    type: damage.itemType,
  };
}

/** What one damage settles at: the reimbursed share, less the deductible. */
function payoutForDamage(items: readonly Item[], damage: Damage): number {
  const reimbursed =
    damage.amount * reimbursementRateOf(damagedItem(items, damage));
  return Math.max(reimbursed - DEDUCTIBLE, NOTHING_PAID_OUT);
}''')
